"""Generated by the NL to Flow Diagram Encoder Pipeline."""

class STACK:
    def __init__(self):
        self.array = []
        self.top = (-1)

    def PUSH(self, element):
        self.top = (self.top + 1)
        self.array[self.top] = element

    def POP(self):
        if (self.top == (-1)):
            return None
        element = self.array[self.top]
        self.top = (self.top - 1)
        return element

    def PEEK(self):
        if (self.top == (-1)):
            return None
        return self.array[self.top]

stack = STACK()

print(stack.PUSH(10))   # None (PUSH returns nothing)
print(stack.PUSH(20))   # None
print(stack.PEEK())     # 20
print(stack.POP())      # 20
print(stack.POP())      # 10
print(stack.POP())      # None (stack empty)
